using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class NotificationRepository(NamaaDbContext db):INotificationRepository{public Task<Notification?>FindByIdAsync(long userId,long id,CancellationToken cancellationToken=default)=>db.Notifications.AsNoTracking().SingleOrDefaultAsync(x=>x.UserId==userId&&x.Id==id,cancellationToken);public Task<Notification?>FindForUpdateAsync(long userId,long id,CancellationToken cancellationToken=default)=>db.Notifications.SingleOrDefaultAsync(x=>x.UserId==userId&&x.Id==id,cancellationToken);public async Task<IReadOnlyList<Notification>>GetAllAsync(long userId,bool? isRead,CancellationToken cancellationToken=default)=>await db.Notifications.AsNoTracking().Where(x=>x.UserId==userId&&(!isRead.HasValue||x.IsRead==isRead.Value)).OrderByDescending(x=>x.CreatedAt).ToListAsync(cancellationToken);}
